/**
 * ShadowTales — shared domain types.
 *
 * The whole app revolves around a serialisable `Story`: a list of characters
 * plus a list of scenes. Keeping the data plain and JSON-safe means the same
 * shape can be produced by the rule-based generator, edited in the studio,
 * stored in localStorage and (later) generated by a language model.
 */

export type Occasion =
  | "wedding"
  | "anniversary"
  | "christmas"
  | "birthday"
  | "friendship"
  | "other";

export type StoryStyle = "romance" | "fantasy" | "comedy" | "hollywood";

export type CharacterType = "human" | "hero" | "wizard" | "child";
export type HairStyle = "short" | "long" | "curly" | "bald";
export type Outfit = "everyday" | "elegant" | "fantasy";
export type Accessory =
  | "none"
  | "flower"
  | "sword"
  | "book"
  | "cup"
  | "crown"
  | "wand";

export interface Character {
  id: string;
  name: string;
  type: CharacterType;
  hair: HairStyle;
  /** Relative body height, 0.8 (small) – 1.2 (tall). */
  height: number;
  glasses: boolean;
  hat: boolean;
  outfit: Outfit;
  accessory: Accessory;
}

export type BackdropId =
  | "party"
  | "castle"
  | "forest"
  | "mountain"
  | "sky"
  | "stars"
  | "home"
  | "street"
  | "beach"
  | "ballroom"
  | "dragon-peak"
  | "proposal";

export type AnimationType =
  | "appear"
  | "walk-in-left"
  | "walk-in-right"
  | "walk-across"
  | "meet"
  | "talk"
  | "turn"
  | "hearts"
  | "fall-object"
  | "zoom"
  | "static"
  | "celebrate"
  | "dragon";

export type MusicMood =
  | "warm"
  | "playful"
  | "epic"
  | "mysterious"
  | "tender"
  | "dramatic";

export interface SceneCharacter {
  characterId: string;
  /** Normalised stage position, 0 (left) – 1 (right). */
  x: number;
  facing: "left" | "right";
  /** Optional entrance delay in seconds. */
  delay?: number;
}

export interface DialogueLine {
  characterId: string;
  text: string;
}

export interface ChoiceOption {
  id: string;
  label: string;
  /** Scene that is played when this option is chosen. */
  nextSceneId: string;
}

export interface SceneChoice {
  prompt: string;
  options: ChoiceOption[];
}

export type CameraMove = "none" | "zoom-in" | "zoom-out" | "pan-left" | "pan-right";

export interface Scene {
  id: string;
  title: string;
  backdrop: BackdropId;
  characters: SceneCharacter[];
  animation: AnimationType;
  camera: CameraMove;
  narration: string;
  dialogue: DialogueLine[];
  /** Playback duration in seconds. */
  duration: number;
  mood: MusicMood;
  /** Optional interactive decision at the end of the scene. */
  choice?: SceneChoice;
  /** Optional large title card, e.g. for the Hollywood style. */
  titleCard?: string;
}

export interface StoryMeta {
  person1: string;
  person2: string;
  date?: string;
  place: string;
  description: string;
}

export interface Story {
  id: string;
  title: string;
  style: StoryStyle;
  occasion: Occasion;
  meta: StoryMeta;
  characters: Character[];
  scenes: Scene[];
  createdAt: string;
  updatedAt: string;
  /** Set when this story is a "what if" variant of another story. */
  variantOf?: string;
  variantLabel?: string;
  /** True for stories that contain interactive decisions. */
  interactive?: boolean;
}

